import * as React from "react";
import { cn } from "../lib/utils";

export type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: "frosted" | "tint" | "ghost";
  size?: "sm" | "md" | "lg";
};

const variantClasses: Record<NonNullable<ButtonProps["variant"]>, string> = {
  frosted:
    "bg-white/10 backdrop-blur-md border border-white/25 text-slate-50 " +
    "shadow-[inset_0_1px_0_rgba(255,255,255,0.18),0_8px_20px_rgba(2,6,23,0.35)] " +
    "hover:bg-white/20 hover:border-white/40 active:bg-white/15",
  tint:
    "bg-sky-400/15 backdrop-blur-md border border-sky-200/30 text-sky-50 " +
    "shadow-[inset_0_1px_0_rgba(255,255,255,0.15),0_8px_20px_rgba(2,6,23,0.30)] " +
    "hover:bg-sky-400/25 hover:border-sky-200/50 active:bg-sky-400/20",
  ghost:
    "bg-transparent border border-transparent text-slate-200 " +
    "hover:bg-white/10 hover:text-white",
};

const sizeClasses: Record<NonNullable<ButtonProps["size"]>, string> = {
  sm: "h-8 px-3 text-sm",
  md: "h-10 px-4 text-sm",
  lg: "h-12 px-6 text-base",
};

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant = "frosted", size = "md", ...props }, ref) => (
    <button
      ref={ref}
      className={cn(
        "inline-flex items-center justify-center gap-2 rounded-lg font-medium tracking-tight",
        "transition-colors duration-150 ease-out select-none cursor-pointer",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/40",
        "disabled:opacity-40 disabled:pointer-events-none",
        variantClasses[variant],
        sizeClasses[size],
        className
      )}
      {...props}
    />
  )
);
Button.displayName = "Button";

export default Button;
```

